'use strict';
const DATA = window.STUDY_DATA;
const FOUNDATION = window.FOUNDATION_DATA;
const KEY = 'nichinichi-v1';
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayKey = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const addDays = (date,n) => { const d = new Date(`${date}T12:00:00`); d.setDate(d.getDate()+n); return dayKey(d); };
const dayDistance = (a,b) => Math.round((new Date(`${b}T12:00:00`)-new Date(`${a}T12:00:00`))/86400000);
const defaultState = () => ({version:1,start:dayKey(),minutes:30,phase:0,level:'foundation',vocabStage:'foundation',wordPractice:[],priorityWords:[],reviews:{},days:{},grammar:{},notes:[],custom:[],assessments:[],materials:[],diagnostic:null,preferences:{theme:'auto',font:'normal',recall:'word'},classDays:{}});
let state, storageAvailable = true;
try { const raw=localStorage.getItem(KEY); state=raw ? validateBackup(JSON.parse(raw)) : defaultState(); } catch { state=defaultState(); storageAvailable=false; }
let today=dayKey(), route='today', studyTab='vocabulary', cardRevealed=false, queue=[], queueActive=false, listeningId=null, selectedChoice=null, listenAnswered=false, showScript=false, audioRate=1, readingId=null, readAnswers={}, readChecked=false, diagnosticIndex=0, diagnosticAnswers=[], diagnosticFinished=false;
let focusRemaining=30*60, focusTotal=30*60, focusRunning=false, focusEnd=0, focusInterval=null, focusedLogged=0, focusLastStamp=0;
let toastTimeout;
const vocab = () => [...DATA.vocabulary,...state.custom];
const currentDay = () => state.days[today] || (state.days[today]={tasks:{},seen:[],newWords:[],focusSeconds:0,listening:[],reading:[]});
function persist() { try { localStorage.setItem(KEY,JSON.stringify(state)); } catch { storageAvailable=false; toast('本机存储不可用，请导出备份，当前页面仍可学习。'); } }
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4200); }
function validateBackup(s) {
  const validDate=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(new Date(`${x}T12:00:00`).getTime());
  const txt=(x,n=1500)=>typeof x==='string'&&x.length<=n;
  const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
  if(!object(s)||s.version!==1||!validDate(s.start)||![30,45,60].includes(s.minutes)||!Number.isInteger(s.phase)||s.phase<0||s.phase>3||!['foundation','n2'].includes(s.level)||!object(s.reviews)||!object(s.days)||!object(s.grammar)||!Array.isArray(s.notes)||!Array.isArray(s.custom)||!Array.isArray(s.assessments))throw Error('备份格式不正确');
  if(s.custom.length>5000||s.notes.length>5000||s.assessments.length>500||Object.keys(s.days).length>4000)throw Error('备份内容过多');
  if(s.materials===undefined)s.materials=[];if(!Array.isArray(s.materials)||s.materials.length>5000)throw Error('教材进度数据有误');for(const m of s.materials)if(!object(m)||!txt(m.id,100)||!validDate(m.date)||!['moji','red','blue','listening','reading'].includes(m.resource)||!txt(m.position,300)||!txt(m.note,2000))throw Error('教材进度数据有误');
  if(s.vocabStage===undefined)s.vocabStage=s.level;
  if(!Object.hasOwn(VOCAB_STAGES,s.vocabStage))throw Error('词汇阶段有误');
  if(s.wordPractice===undefined)s.wordPractice=[];
  if(s.priorityWords===undefined)s.priorityWords=[];
  if(!Array.isArray(s.wordPractice)||s.wordPractice.length>1000)throw Error('听写记录有误');
  const ids=new Set(DATA.vocabulary.map(x=>x.id));
  for(const c of s.custom){if(!object(c)||!txt(c.id,100)||!c.id.startsWith('c-')||ids.has(c.id)||!['foundation','n2'].includes(c.level)||!txt(c.word,100)||!c.word.trim()||!txt(c.reading,150)||!txt(c.meaning,300)||!c.meaning.trim()||!txt(c.example,1000)||!txt(c.exampleZh,1000))throw Error('单词数据有误');ids.add(c.id);}
  for(const c of s.custom)if(c.stage!==undefined&&!Object.hasOwn(VOCAB_STAGES,c.stage))throw Error('自添词阶段有误');
  if(!Array.isArray(s.priorityWords)||s.priorityWords.length>5000||s.priorityWords.some(id=>!ids.has(id))||new Set(s.priorityWords).size!==s.priorityWords.length)throw Error('优先词记录有误');
  for(const r of s.wordPractice)if(!object(r)||!ids.has(r.id)||!validDate(r.date)||typeof r.correct!=='boolean')throw Error('听写记录有误');
  for(const [id,r] of Object.entries(s.reviews)){if(!ids.has(id)||!object(r)||!validDate(r.due)||!Number.isInteger(r.stage)||r.stage< -1||r.stage>4||!Number.isInteger(r.reps)||r.reps<0)throw Error('复习数据有误');}
  for(const [d,v] of Object.entries(s.days)){if(!validDate(d)||!object(v)||!object(v.tasks)||!Array.isArray(v.seen)||v.seen.some(x=>!ids.has(x))||!Number.isFinite(v.focusSeconds)||v.focusSeconds<0||v.focusSeconds>86400||!Array.isArray(v.listening)||!Array.isArray(v.reading))throw Error('打卡数据有误');if(v.newWords===undefined)v.newWords=[];if(!Array.isArray(v.newWords)||v.newWords.some(x=>!ids.has(x)))throw Error('新词数据有误');for(const [t,b]of Object.entries(v.tasks))if(!['vocabulary','listening','grammar_reading'].includes(t)||typeof b!=='boolean')throw Error('任务数据有误');}
  for(const [id,v] of Object.entries(s.grammar))if(!DATA.grammar.some(g=>g.id===id)||!validDate(v))throw Error('语法数据有误');
  for(const n of s.notes)if(!object(n)||!txt(n.id,100)||!txt(n.title,300)||!txt(n.body,5000)||!txt(n.type,30)||!validDate(n.date))throw Error('笔记数据有误');
  for(const a of s.assessments)if(!object(a)||!validDate(a.date)||!txt(a.source,300)||!txt(a.note,2000)||!['language','reading','listening'].every(k=>Number.isFinite(a[k])&&a[k]>=0&&a[k]<=100))throw Error('测评数据有误');
  if(s.diagnostic!==null&&(!object(s.diagnostic)||!validDate(s.diagnostic.date)||!Number.isInteger(s.diagnostic.score)||s.diagnostic.score<0||s.diagnostic.score>FOUNDATION.diagnostic.length||!Array.isArray(s.diagnostic.weakAreas)||s.diagnostic.weakAreas.some(x=>!txt(x,100))))throw Error('自测数据有误');
  if(s.preferences===undefined)s.preferences={theme:'auto',font:'normal',recall:'word'};
  if(!object(s.preferences)||!['auto','light','dark'].includes(s.preferences.theme)||!['normal','large'].includes(s.preferences.font)||!['word','meaning'].includes(s.preferences.recall))throw Error('显示设置有误');
  if(s.classDays===undefined)s.classDays={};
  if(!object(s.classDays)||Object.keys(s.classDays).length>4000)throw Error('课堂记录有误');
  const choice=x=>x===null||(Number.isInteger(x)&&x>=0&&x<=2);
  for(const [date,d]of Object.entries(s.classDays)){
    if(!validDate(date)||!object(d)||!/^foundation-0[1-7]$/.test(d.lessonId)||!Number.isInteger(d.step)||d.step<0||d.step>5||!Array.isArray(d.done)||d.done.length>6||new Set(d.done).size!==d.done.length||d.done.some(x=>!Number.isInteger(x)||x<0||x>5)||!txt(d.draft,2000)||typeof d.modelShown!=='boolean'||typeof d.transcriptShown!=='boolean'||!choice(d.listenAnswer)||typeof d.listenChecked!=='boolean'||!Array.isArray(d.quiz)||d.quiz.length!==3||!d.quiz.every(choice)||typeof d.quizChecked!=='boolean'||typeof d.touched!=='boolean')throw Error('课堂记录有误');
    if(d.quizChecked&&d.quiz.some(x=>x===null))throw Error('课堂测验记录不完整');
    if(d.listenChecked&&d.listenAnswer===null)throw Error('课堂听力记录不完整');
  }
  return s;
}
const icons={today:'<rect x="3" y="4" width="18" height="17" rx="3"/><path d="M7 2v4m10-4v4M3 10h18m-13 5 3 3 5-6"/>',study:'<path d="M12 5c-3-3-7-3-10-1v15c3-2 7-2 10 1 3-3 7-3 10-1V4c-3-2-7-2-10 1Zm0 0v15"/>',plan:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h9a4 4 0 0 1 0 8H8a4 4 0 0 0 0 6h9"/>',notes:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>'};
const icon=(id)=>`<svg viewBox="0 0 24 24" class="nav-icon" aria-hidden="true">${icons[id]}</svg>`;
const navItems=[['today','今日学习'],['study','学习空间'],['plan','备考路线'],['notes','积累手账']];
function nav(){const html=navItems.map(([id,title])=>`<a class="nav-item ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span></a>`).join('');$('#desktop-nav').innerHTML=html;$('#mobile-nav').innerHTML=html;}
function heading(title,subtitle,tag='每天 '+state.minutes+' 分钟'){return `<div class="heading"><div><h1>${title}</h1><p>${subtitle}</p></div><span class="heading-tag">${esc(tag)}</span></div>`;}
function tasks(){const list=DATA.plan.daily[state.minutes];const reading=dayDistance(state.start,today)%2!==0;return list.map(t=>({...t,name:t.type==='vocabulary'?'词汇 · 温习旧词，认识新词':t.type==='listening'?'听力 · 把熟悉的词听出来':reading?'阅读 · 找到句子的线索':'语法 · 找回句子的骨架',hint:t.label,tab:t.type==='grammar_reading'?(reading?'reading':'grammar'):t.type}));}
function getDue(){return vocab().filter(v=>state.reviews[v.id]&&state.reviews[v.id].due<=today);}
function activeDays(){return Object.entries(state.days).filter(([,v])=>Object.values(v.tasks).some(Boolean)||v.focusSeconds>0||v.seen.length).length;}
function completedMinutes(d=currentDay()){return tasks().reduce((n,t)=>n+(d.tasks[t.type]?t.minutes:0),0);}
function weekChart(){const dates=Array.from({length:7},(_,i)=>addDays(today,i-6));return `<div class="week-chart">${dates.map(d=>{const v=state.days[d];const count=v?['vocabulary','listening','grammar_reading'].filter(t=>v.tasks[t]).length:0;return `<div class="week-col ${d===today?'today':''}"><div class="week-track" title="${d} 完成 ${count}/3 项"><div class="week-bar" style="height:${count/3*100}%"></div></div><span>${['日','一','二','三','四','五','六'][new Date(`${d}T12:00:00`).getDay()]}</span></div>`;}).join('')}</div>`;}
function wave(){return `<div class="wave" aria-hidden="true">${Array.from({length:38},(_,i)=>`<i style="--h:${[7,12,19,26,14,33,22,11][i%8]}px"></i>`).join('')}</div>`;}
function renderToday(){const d=currentDay(),done=completedMinutes(d),due=getDue().length,known=Object.keys(state.reviews).length,weekReview=new Date(`${today}T12:00:00`).getDay()===0,stage=DATA.plan.phases[state.phase],elapsed=Math.max(1,dayDistance(state.start,today)+1);return `${heading('把日语，一点点找回来。','先补基础，再向 2027 年夏季 N2 稳步前进。','你的 30 分钟起点')}
  <section class="hero"><div><span class="eyebrow"><i class="dot"></i>${state.phase===0?'基础恢复':'稳步进阶'} · 第 ${elapsed} 天</span><h2>${state.phase===0?'先把基础找回来。':'每天积累，都有回响。'}</h2><p>不急着追难题。今天，也从一点点开始。</p><button class="button" data-action="start-today">开始今日学习 <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><i class="circle"></i><i class="orb"></i><i class="book"></i><i class="stem"></i><i class="leaf"></i><i class="leaf two"></i><span class="caption">日々、一歩ずつ。</span></div></section>
  ${!state.diagnostic?'<div class="onboarding"><div><strong>从你会的地方开始。</strong><p>8 道基础小题，找出现在需要复习的部分。</p></div><button class="button ghost" data-action="diagnostic">做个小测 ↗</button></div>':''}
  <div class="stats"><div class="stat"><div class="stat-icon">◷</div><div><small>今日计划完成</small><strong>${done}<span>/ ${state.minutes} 分钟</span></strong></div></div><div class="stat"><div class="stat-icon">✦</div><div><small>累计学习日</small><strong>${activeDays()}<span>天</span></strong></div></div><div class="stat"><div class="stat-icon">文</div><div><small>已接触词汇</small><strong>${known}<span>个</span></strong></div></div><div class="stat"><div class="stat-icon">↻</div><div><small>今天到期复习</small><strong>${due}<span>个</span></strong></div></div></div>
  <div class="dashboard"><div><section class="card"><div class="card-head"><h2>今日的小目标</h2><small>${state.minutes} 分钟 · 基础优先</small></div><div class="progress-banner"><div class="progress-ring" style="--value:${Math.round(done/state.minutes*100)}"><span>${Math.round(done/state.minutes*100)}%</span></div><div><strong>${done===state.minutes?'今天的小目标，完成了。':'三个小步骤，慢慢来。'}</strong><p>复习在先，听力每天都留一点时间。</p></div></div>${tasks().map(t=>`<div class="task"><button class="check ${d.tasks[t.type]?'done':''}" aria-label="${d.tasks[t.type]?'取消完成':'标记完成'}：${esc(t.name)}" aria-pressed="${!!d.tasks[t.type]}" data-action="toggle-task" data-id="${t.type}">${d.tasks[t.type]?'✓':''}</button><div class="task-detail"><strong>${t.name}</strong><small>${esc(t.hint)}</small></div><span class="task-time">${t.minutes} 分钟</span><button class="tiny" data-action="study-tab" data-id="${t.tab}" aria-label="开始${esc(t.name)}">↗</button></div>`).join('')}<p class="panel-note">完成后勾选。上方分钟数按任务计划估算；实际专注时间由计时器记录。</p><div class="button-row section-gap"><button class="button ghost" data-action="timer">◷ 打开专注计时</button><button class="text-link" data-action="plan">看看完整计划 →</button></div></section><section class="card"><div class="card-head"><h2>一周的脚印</h2><small>最近 7 天</small></div>${weekChart()}<div class="week-legend"><span>柱高 = 当天完成的任务比例</span><span>不补打卡，继续向前。</span></div></section></div>
  <div class="right-col"><section class="card mini-card"><span class="eyebrow">温故，才能知新</span><span class="mini-number">${due.toString().padStart(2,'0')}</span><h2 style="margin-top:15px">今天该见的词，<br>再见一面。</h2><p>${due?'先复习到期词，再决定是否加入新词。':weekReview?'今天是复习日，回看本周学过的词和笔记。':'今天没有到期词，可以认识最多 5 个新词。'}<br>忘记很正常，下一次会更熟悉。</p><button class="button" data-action="study-tab" data-id="vocabulary">${due?'去复习':weekReview?'回看旧词':'去学词'} →</button></section><section class="card listen-card"><div class="card-head"><h2>听力小练习</h2><span class="pill">${state.level==='foundation'?'基础恢复':'N2 拓展'}</span></div><p class="subtext">先听，不看文本。把熟悉的日语<br>从纸上，带到耳朵里。</p>${wave()}<button class="button secondary full" data-action="study-tab" data-id="listening">▷ 开始精听</button><p class="panel-note">设备日语合成语音练习；真人听力请使用官方资料。</p></section><section class="card"><span class="eyebrow">现在的学习阶段</span><h3 style="margin-top:13px">${esc(stage.title.replace(/第 \d 阶段 · /,''))}</h3><p class="subtext">${esc(stage.focus)}</p><button class="text-link" data-action="plan">查看阶段目标 →</button></section></div></div>`;}
function renderStudy(){if(studyTab==='materials')return `${heading('把教材变成每天的一点。','MOJi、红宝书与蓝宝书，按你的节奏配合学习。')}<div class="tabs" role="tablist">${[['vocabulary','词汇复习'],['grammar','语法笔记'],['listening','听力练习'],['reading','短文阅读'],['materials','教材与课程']].map(([id,title])=>`<button role="tab" aria-selected="${studyTab===id}" class="tab ${studyTab===id?'active':''}" data-action="study-tab" data-id="${id}">${title}</button>`).join('')}</div>${renderMaterials()}`;return `${heading('在这里，慢慢学。','先温习基础，留下今天学会的一点。')}<div class="tabs" role="tablist">${[['vocabulary','词汇复习'],['grammar','语法笔记'],['listening','听力练习'],['reading','短文阅读'],['materials','教材与课程']].map(([id,title])=>`<button role="tab" aria-selected="${studyTab===id}" class="tab ${studyTab===id?'active':''}" data-action="study-tab" data-id="${id}">${title}</button>`).join('')}</div>${studyTab==='vocabulary'?vocabularyStagePicker():`<div class="filter-row"><label class="visually-hidden" for="level">内容阶段</label><select id="level"><option value="foundation" ${state.level==='foundation'?'selected':''}>基础恢复 · N4—N3</option><option value="n2" ${state.level==='n2'?'selected':''}>N2 拓展</option></select><small>练习分类用于选内容，不代表官方分级。</small></div>`}${studyTab==='vocabulary'?renderVocabulary():studyTab==='grammar'?renderGrammar():studyTab==='listening'?renderListening():renderReading()}`;}
function buildQueue(){const due=getDue();const allowance=Math.max(0,5-currentDay().newWords.length);const weekReview=new Date(`${today}T12:00:00`).getDay()===0;const words=vocab(),priority=state.priorityWords.map(id=>words.find(v=>v.id===id)).filter(v=>v&&!state.reviews[v.id]);const fresh=[...priority,...words.filter(v=>vocabStage(v)===state.vocabStage&&!state.reviews[v.id]&&!state.priorityWords.includes(v.id))].slice(0,weekReview?0:allowance);queue=due.map(v=>v.id).concat(fresh.map(v=>v.id));queueActive=true;cardRevealed=false;}
function renderVocabulary(){if(!queueActive)buildQueue();const v=vocab().find(v=>v.id===queue[0]);const known=Object.keys(state.reviews).length;return `${vocabularyOverview()}<div class="split"><div><div class="card study-card"><div class="status-row full"><span>${v?(state.reviews[v.id]?'到期复习':'今日新词'):'今日词卡'}</span><span>${queue.length} 张待学</span></div>${v?`<span class="pill">${stageTitle(v)}${v.topic?' · '+esc(v.topic):''}</span><div class="word jp">${esc(v.word)}</div><button class="text-link" data-action="speak-word" data-id="${esc(v.id)}">${wordAudioButtonLabel(v)}</button>${wordVoiceLinks(v)}${cardRevealed?`<div class="answer"><div class="reading jp">${esc(v.reading)}</div><div class="meaning">${esc(v.meaning)}</div>${vocabularyDetail(v)}</div><div class="button-row"><button class="button orange" data-action="rate" data-id="again">忘了 · 再练</button><button class="button ghost" data-action="rate" data-id="hard">不熟 · 明天</button><button class="button" data-action="rate" data-id="good">记得 · 下一张</button></div>`:'<p class="subtext section-gap">先想想读音和意思，再翻开答案。</p><button class="button section-gap" data-action="reveal-card">翻开词卡 ↓</button>'}`:`<div style="font-size:44px;color:var(--muted);margin:30px">✓</div><h2>今天的词卡，先到这里。</h2><p class="subtext">${new Date(`${today}T12:00:00`).getDay()===0?'周日只复习旧词。':'每日最多 5 个新词。今天可继续听音、查词，或加入自己的词句。'}<br>下一次到期时，词卡会回来。</p><div class="button-row"><button class="button ghost" data-action="add-word">＋ 添加自己的词</button><button class="button" data-action="complete-vocab">完成词汇任务</button></div>`}</div><p class="subtext">简化间隔复习：记得后按 1 → 3 → 7 → 14 → 30 天再见；忘记则当天再练、次日复习。不熟则次日再见。到期词始终优先。</p></div><div><section class="card"><div class="card-head"><h2>你的词汇积累</h2><button class="text-link" data-action="add-word">＋ 添词</button></div><div class="metric-grid"><div class="metric"><strong>${known}</strong><small>接触过的词</small></div><div class="metric"><strong>${getDue().length}</strong><small>今天到期</small></div><div class="metric"><strong>${state.custom.length}</strong><small>自添词句</small></div></div><p class="panel-note">「接触过」不是「已掌握」。内置 ${DATA.vocabulary.length.toLocaleString()} 个词条，含320张搭配与例句详解卡。新增词条配中文词典释义；仍需结合教材练习实际用法。</p></section>${wordAudioResourceCard()}<section class="card"><h2>让一个词真的留下来</h2><ol class="info-list"><li>看日语，回想读音和意思。</li><li>说出例句，连接文字与声音。</li><li>诚实选「忘了 / 不熟 / 记得」。</li><li>复习超时就停，新词明天再加。</li></ol><p class="panel-note">可以把教材、阅读里的词加入本站。未知词是否属于官方 N2 清单，本站不作判断。</p></section></div></div>`;}
function rateCard(rating){const id=queue.shift();if(!id)return;state.priorityWords=state.priorityWords.filter(x=>x!==id);if(!state.reviews[id])currentDay().newWords.push(id);const old=state.reviews[id]||{stage:-1,reps:0};const stage=rating==='good'?Math.min(old.stage+1,4):rating==='again'?-1:old.stage;state.reviews[id]={stage,reps:old.reps+1,due:addDays(today,rating==='good'?[1,3,7,14,30][stage]:1)};if(rating==='again'){queue.push(id);state.reviews[id].due=today;}if(!currentDay().seen.includes(id))currentDay().seen.push(id);if(rating==='again')addNote('vocab-'+id,'易忘词：'+vocab().find(v=>v.id===id).word,'读音：'+vocab().find(v=>v.id===id).reading+'；意思：'+vocab().find(v=>v.id===id).meaning+'。下次先回想，再看答案。','词汇');cardRevealed=false;persist();render();}
function renderGrammar(){const gs=DATA.grammar.filter(g=>g.level===state.level);return `<div class="notice">每周约 3 个语法点就够了。先辨认接续，再自己造一句。用「学过」记录接触情况，隔天回看能否脱离笔记想起来。</div><div class="grammar-grid">${gs.map(g=>`<article class="card grammar-card"><div class="card-head"><span class="pill">${g.level==='foundation'?'基础恢复':'N2 拓展'}</span><button class="text-link" data-action="save-grammar" data-id="${g.id}">＋ 收藏</button></div><h2 class="grammar-title jp">${esc(g.title)}</h2><p class="grammar-usage">${esc(g.usage)}</p><div class="example jp">${esc(g.example)}<div class="translation">${esc(g.exampleZh)}</div></div><div class="button-row section-gap"><button class="button ${state.grammar[g.id]?'secondary':'ghost'}" data-action="learn-grammar" data-id="${g.id}">${state.grammar[g.id]?'✓ 学过 · 再回想':'标记学过'}</button><button class="text-link" data-action="speak-grammar" data-id="${g.id}">▷ 听例句</button></div></article>`).join('')}</div>`;}
function activeListen(){const items=DATA.listening.filter(l=>l.level===state.level);if(!items.some(l=>l.id===listeningId))listeningId=items[dayDistance(state.start,today)%items.length]?.id||items[0].id;return DATA.listening.find(l=>l.id===listeningId);}
function renderListening(){const l=activeListen();const items=DATA.listening.filter(x=>x.level===state.level);return `<div class="split"><section class="card"><div class="card-head"><h2>${esc(l.title)}</h2><small>原创短对话</small></div><label class="visually-hidden" for="listening-pick">选择听力</label><select id="listening-pick">${items.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div class="audio-player">${wave()}<div class="audio-controls"><button class="button" data-action="play-listening">▷ 播放日语</button><button class="button ghost" data-action="stop-speech">停止</button><label class="visually-hidden" for="audio-speed">播放速度</label><select id="audio-speed"><option value="0.8" ${audioRate===0.8?'selected':''}>0.8 × 精听</option><option value="1" ${audioRate===1?'selected':''}>1.0 × 正常</option><option value="1.15" ${audioRate===1.15?'selected':''}>1.15 × 稍快</option></select></div><p class="panel-note" style="text-align:center">使用设备日语合成语音。若设备未提供日语声音，请到官方资料练真人听力。</p></div><p class="question jp">${esc(l.question)}</p>${l.options.map((o,i)=>`<button class="choice ${selectedChoice===i?'selected':''} ${listenAnswered&&i===l.answer?'correct':''} ${listenAnswered&&selectedChoice===i&&i!==l.answer?'wrong':''}" data-action="listen-choice" data-id="${i}" ${listenAnswered?'disabled':''}><b>${'ABCD'[i]}</b><span class="jp">${esc(o)}</span></button>`).join('')}${listenAnswered?`<div class="feedback ${selectedChoice!==l.answer?'wrong':''}"><strong>${selectedChoice===l.answer?'答对了，找到了关键信息。':'再听一次，留意行动顺序。'}</strong><br>${esc(l.explanation)}</div>`:`<button class="button section-gap" data-action="check-listening" ${selectedChoice===null?'disabled':''}>提交答案</button>`}<div class="button-row section-gap"><button class="button ghost" data-action="toggle-script">${showScript?'收起文本':'查看文本'}</button><button class="text-link" data-action="reset-listening">再练一次</button></div>${showScript?`<div class="transcript jp">${esc(l.script)}</div><p class="panel-note">逐句跟读两遍后，收起文本再听。</p>`:''}</section><div><section class="card"><h2>${DATA.plan.daily[state.minutes].find(t=>t.type==='listening').minutes} 分钟的精听循环</h2><ol class="info-list">${DATA.plan.listeningLoop.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button class="button ghost full section-gap" data-action="complete-listening">完成精听，记入今日任务</button><p class="panel-note">答完题只是第一步，完成跟读和无稿复听后再勾选。</p></section><section class="card"><h2>真人听力入口</h2><p class="subtext">适应真实语速、多人对话和题型时，用官方练习册配套音频。不要只依赖合成语音。</p>${location.protocol==='file:'?`<a class="button full" style="margin-bottom:12px" href="${/\/index\.html$/i.test(location.pathname||'')?'../':'./'}JLPT-官方真人听力-2012/index.html" target="_blank" rel="noopener">▷ 播放已下载的官方真人听力</a><p class="panel-note">N4 → N3 → N2，附题目、答案与原文。播放器支持调速与 A/B 循环。音频是整组练习，与上方原创示例题分别使用。</p>` : ''}<a class="button secondary" href="https://www.jlpt.jp/e/samples/sampleindex.html" target="_blank" rel="noopener">打开 JLPT 官方练习 ↗</a></section></div></div>`;}
function renderReading(){const items=FOUNDATION.reading;if(state.level==='n2')return '<div class="card"><h2>N2 阅读，用官方材料练。</h2><p class="subtext">初版内置的是基础短阅读。N2 阶段请从官方练习册选择新文章，计时后记录正确率和错因。</p><div class="button-row"><a class="button" target="_blank" rel="noopener" href="https://www.jlpt.jp/e/samples/sampleindex.html">官方练习册 ↗</a><button class="button ghost" data-action="assessment">记录测评结果</button></div></div>';if(!items.some(r=>r.id===readingId))readingId=items[0].id;const r=items.find(x=>x.id===readingId);return `<div class="split"><section class="card"><div class="card-head"><h2>${esc(r.title)}</h2><span class="pill">基础短阅读</span></div><label class="visually-hidden" for="reading-pick">选择短文</label><select id="reading-pick">${items.map(x=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div class="transcript jp">${esc(r.text)}</div>${r.questions.map((q,qi)=>`<p class="question jp">${qi+1}. ${esc(q.prompt)}</p>${q.choices.map((c,i)=>`<button class="choice ${readAnswers[qi]===i?'selected':''} ${readChecked&&i===q.answer?'correct':''} ${readChecked&&readAnswers[qi]===i&&i!==q.answer?'wrong':''}" data-action="read-choice" data-id="${qi}:${i}" ${readChecked?'disabled':''}><b>${'ABCD'[i]}</b><span class="jp">${esc(c)}</span></button>`).join('')}${readChecked?`<div class="feedback ${readAnswers[qi]!==q.answer?'wrong':''}">${esc(q.explanation)}</div>`:''}`).join('')}${!readChecked?`<button class="button section-gap" data-action="check-reading" ${r.questions.some((_,i)=>readAnswers[i]===undefined)?'disabled':''}>提交阅读答案</button>`:`<div class="transcript"><h3>对照译文</h3><p class="subtext">${esc(r.translation)}</p></div><button class="button ghost section-gap" data-action="reset-reading">重新练习</button>`}</section><section class="card" style="align-self:start"><h2>读懂，比读快更重要。</h2><ol class="info-list"><li>先看问题，知道要找什么。</li><li>读短文，标出时间、条件和行动。</li><li>找到支持答案的原句。</li><li>只查影响理解的词，加入词卡。</li></ol><button class="button ghost full" data-action="add-word">＋ 收集一个词</button></section></div>`;}
function renderPlan(){return `${heading('朝着 N2，一步一步。','基础恢复 → N3 桥接 → N2 专项 → 检验查漏','JLPT N2')}<div class="notice">默认每天 ${state.minutes} 分钟，前期补基础。N1 放在 N2 之后规划。考试日期和报名安排请查看当地官方公告；阶段时长可按实际表现调整。</div><div class="split"><div class="timeline">${DATA.plan.phases.map((p,i)=>`<div class="phase ${state.phase===i?'current':''}"><span class="phase-number">${i+1}</span><section class="card"><div class="phase-period">${esc(p.period)}</div><div class="card-head"><h2>${esc(p.title.replace(/第 \d 阶段 · /,''))}</h2>${state.phase===i?'<span class="pill">当前阶段</span>':''}</div><p class="subtext">${esc(p.focus)}</p><ul>${p.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul>${state.phase!==i?`<button class="text-link" data-action="set-phase" data-id="${i}">将此阶段设为当前 →</button>`:''}</section></div>`).join('')}</div><div><section class="card"><h2>你的每日安排</h2><div class="table-wrap"><table><thead><tr><th>内容</th><th>时间</th></tr></thead><tbody>${DATA.plan.daily[state.minutes].map(t=>`<tr><td>${esc(t.label)}</td><td style="white-space:nowrap">${t.minutes} 分钟</td></tr>`).join('')}</tbody></table></div><p class="subtext section-gap">${esc(DATA.plan.reviewPolicy.weekly)}</p><p class="panel-note">${esc(DATA.plan.reviewPolicy.optionalWeekend)}</p></section><section class="card"><h2>第一阶段，每周补什么</h2><ul class="info-list"><li>第 1–2 周：助词、句子结构、动词 ます / て / ない / た 形。</li><li>第 3–4 周：可能形、授受、经历、意图、目的和条件。</li><li>第 5–6 周：连接句子、短文理解、日常任务听力。</li><li>第 7–8 周：按新题测评结果补漏；基础稳定可提前桥接。</li></ul><button class="button ghost" data-action="diagnostic">做基础小测</button></section><section class="card"><h2>每四周，看一次真实进步</h2><p class="subtext">记下各项正确率、用时和错因。尽量用没练过的题，打卡天数不能替代水平。</p><button class="button secondary" data-action="assessment">＋ 记录一次测评</button><p class="panel-note">每天 30 分钟，约九个月共 130 小时。N2 是否来得及，需要用测评判断，不能仅凭高考或四级成绩推断。</p></section><section class="card"><h2>考试与资料</h2><p class="subtext">N2 合格要求：总分至少 90 / 180，语言知识、阅读、听力各至少 19 / 60。练习正确率不能直接换算正式分数。</p><a class="text-link" href="https://www.jlpt.jp/e/guideline/results.html" target="_blank" rel="noopener">查看官方合格标准 ↗</a><div class="resource"><a href="https://www.jlpt.jp/e/samples/sampleindex.html" target="_blank" rel="noopener"><strong>官方练习册与听力 ↗</strong></a><p>用于了解题型、阶段评估和后期计时练习。</p></div></section></div></div>${githubLearningReferences()}`;}
function renderNotes(){const known=Object.keys(state.reviews).length;return `${heading('把今天留下来。','易忘词、错题和你的发现，都值得再见一次。','记录可导出')}<div class="stats"><div class="stat"><div><small>学习日</small><strong>${activeDays()}<span>天</span></strong></div></div><div class="stat"><div><small>接触词汇</small><strong>${known}<span>个</span></strong></div></div><div class="stat"><div><small>收藏与笔记</small><strong>${state.notes.length}<span>条</span></strong></div></div><div class="stat"><div><small>实际专注</small><strong>${Math.floor(Object.values(state.days).reduce((n,d)=>n+d.focusSeconds,0)/60)}<span>分钟</span></strong></div></div></div><div class="split"><section class="card"><div class="card-head"><h2>我的积累</h2><button class="text-link" data-action="add-note">＋ 写一条</button></div>${state.notes.length?state.notes.slice().reverse().map(n=>`<article class="note-item"><div class="card-head" style="margin-bottom:0"><strong>${esc(n.title)}</strong><button class="text-link danger" data-action="delete-note" data-id="${esc(n.id)}">删除</button></div><p style="white-space:pre-wrap">${esc(n.body)}</p><span class="note-date">${esc(n.date)} · ${esc(n.type)}</span></article>`).join(''):'<div class="empty">这里还没有笔记。<br>遇到容易忘的词，或者答错的题，<br>留下一句自己的解释。</div>'}</section><div><section class="card"><div class="card-head"><h2>阶段测评记录</h2><button class="text-link" data-action="assessment">＋ 记录</button></div>${state.assessments.length?state.assessments.slice().reverse().map(a=>`<div class="note-item"><strong>${esc(a.source)}</strong><p>词汇语法 ${a.language}% · 阅读 ${a.reading}% · 听力 ${a.listening}%</p><p>${esc(a.note)}</p><small class="muted">${a.date} · 练习正确率，不等于 JLPT 分数</small></div>`).join(''):'<p class="subtext">每四周记录一次。先和过去的自己比较，再判断下一阶段怎么安排。</p>'}</section>${state.diagnostic?`<section class="card"><h2>上次基础小测</h2><p class="subtext">${state.diagnostic.date} · ${state.diagnostic.score} / ${FOUNDATION.diagnostic.length} 题</p><p class="subtext">复习重点：${esc(state.diagnostic.weakAreas.join('、')||'本组题已答对，继续用新题检验。')}</p><button class="text-link" data-action="diagnostic">重新做基础小测 →</button></section>`:''}<section class="card"><h2>我的自添词句</h2>${state.custom.length?state.custom.map(w=>`<span class="word-chip">${esc(w.word)} <small>${esc(w.meaning)}</small></span>`).join(''):'<p class="subtext">把阅读或教材里的词加入词卡，它们也会按间隔安排复习。</p>'}<button class="button ghost section-gap" data-action="add-word">＋ 添加单词</button></section><section class="card"><h2>备份，让积累跟你走。</h2><p class="subtext">记录只保存在当前浏览器。换手机、换电脑前导出备份，再到新设备导入；没有自动云同步。</p><button class="button secondary" data-action="export">导出学习备份 ↓</button></section></div></div>`;}
function renderDiagnostic(){const qs=FOUNDATION.diagnostic;if(diagnosticFinished){const score=diagnosticAnswers.reduce((n,a,i)=>n+(a===qs[i].answer),0);const wrong=qs.filter((q,i)=>diagnosticAnswers[i]!==q.answer);return `${heading('知道哪里忘了，就有了起点。','基础小测用来选择复习重点，不用来判定 JLPT 等级。')}<div class="card"><div class="metric-grid"><div class="metric"><strong>${score} / ${qs.length}</strong><small>本组答对题数</small></div><div class="metric"><strong>${Math.round(score/qs.length*100)}%</strong><small>这组练习正确率</small></div><div class="metric"><strong>${new Set(wrong.map(q=>q.area)).size}</strong><small>需要回看的部分</small></div></div><p class="subtext section-gap">${score>=6?'本组基础题大多能理解。继续练新题和短听力，检查动词变形与理解是否稳定。':'先把错题涉及的基础找回来，接下来的两周围绕这些内容练习。'}</p>${wrong.map(q=>`<div class="note-item"><strong>${esc(q.area)}</strong><p class="jp">${esc(q.prompt)}</p><p>正确答案：${esc(q.choices[q.answer])}<br>${esc(q.explanation)}</p></div>`).join('')}<div class="button-row"><button class="button" data-action="study-tab" data-id="grammar">开始基础恢复 →</button><button class="button ghost" data-action="today">回到今天</button></div></div>`;}const q=qs[diagnosticIndex];return `${heading('先看看，哪些基础还记得。','只需几分钟；答完再看解释。不会也没关系。','基础小测')}<div class="card" style="max-width:760px;margin:auto"><p class="diagnostic-step">第 ${diagnosticIndex+1} / ${qs.length} 题 · ${esc(q.area)}</p><h2 class="jp">${esc(q.prompt)}</h2>${q.choices.map((c,i)=>`<button class="choice ${diagnosticAnswers[diagnosticIndex]===i?'selected':''}" data-action="diagnostic-choice" data-id="${i}"><b>${'ABCD'[i]}</b><span class="jp">${esc(c)}</span></button>`).join('')}<button class="button section-gap" data-action="diagnostic-next" ${diagnosticAnswers[diagnosticIndex]===undefined?'disabled':''}>${diagnosticIndex===qs.length-1?'查看结果':'下一题 →'}</button><p class="panel-note">原创 8 题，不足以预测正式考试成绩。</p></div>`;}
function render(){if(dayKey()!==today){today=dayKey();queueActive=false;queue=[];}nav();$('#date-label').textContent=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());$('.local-tag').innerHTML=`<i></i>${storageAvailable?'记录保存在本机':'存储不可用，请备份'}`;$('#app').innerHTML=route==='today'?renderToday():route==='study'?renderStudy():route==='plan'?renderPlan():route==='diagnostic'?renderDiagnostic():renderNotes();}
function go(r){if(typeof stopWordAudio==='function')stopWordAudio();if('speechSynthesis'in window)window.speechSynthesis.cancel();route=r;if(r==='diagnostic'){diagnosticIndex=0;diagnosticAnswers=[];diagnosticFinished=false;}if(location.hash!==`#${r}`)history.replaceState(null,'',`#${r}`);render();window.scrollTo({top:0,behavior:'instant'});}
function study(tab){studyTab=tab;selectedChoice=null;listenAnswered=false;showScript=false;go('study');}
function addNote(id,title,body,type){title=String(title).slice(0,300);const existing=state.notes.find(n=>n.id===id);if(existing){existing.date=today;existing.body=body;return;}state.notes.push({id,title,body,type,date:today});}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭">×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal();}
function settings(){modal('学习设置与备份',`<p class="subtext">时间可以调整，基础恢复优先的安排会保留。</p><label class="subtext">每天学习时间<select id="minutes-pick">${[30,45,60].map(n=>`<option value="${n}" ${state.minutes===n?'selected':''}>${n} 分钟</option>`).join('')}</select></label><div class="settings-actions"><button class="button secondary" data-action="export">↓ 导出备份（包含词卡、记录与笔记）</button><label class="button ghost" for="backup-file">↑ 导入备份（替换当前记录）</label><input type="file" id="backup-file" accept="application/json,.json" class="visually-hidden"></div><p class="subtext">本站记录保存在当前设备的浏览器里。手机与电脑不会自动同步；请定期导出备份。导入前会再次展示记录数量，由你确认替换。</p><div class="notice">本地雏形可以打开文件查看。部署后可在手机浏览器访问，并在支持的浏览器中添加到主屏幕、缓存离线内容；这些手机功能尚未实机验证。合成语音取决于设备提供的日语声音。</div><p class="panel-note">${esc(DATA.contentNote)}</p>`);}
function addWord(){modal('把一个词留下来',`<form id="word-form" class="form-grid"><label>日语单词 *<input name="word" required maxlength="100" placeholder="例如：間に合う"></label><label>读音<input name="reading" maxlength="150" placeholder="まにあう"></label><label class="wide">中文意思 *<input name="meaning" required maxlength="300" placeholder="赶得上；来得及"></label><label class="wide">日语例句<textarea name="example" maxlength="1000" rows="2"></textarea></label><label class="wide">例句中文<textarea name="exampleZh" maxlength="1000" rows="2"></textarea></label><label class="wide">学习分类<select name="stage">${stageOptions(state.vocabStage)}</select></label><button type="submit" class="button wide">保存到词卡</button></form><p class="panel-note">分类由你选择，用于安排内容；不代表官方 JLPT 分级。新词会进入每日最多 5 张的队列。</p>`);}
function addNoteForm(){modal('写下一点发现',`<form id="note-form"><label class="subtext">标题<input name="title" required maxlength="300" placeholder="例如：今天终于听清了长音"></label><label class="subtext section-gap">笔记<textarea name="body" required maxlength="5000" rows="5" placeholder="写下错因、例句，或者下次想注意的事。"></textarea></label><button class="button section-gap" type="submit">保存笔记</button></form>`);}
function assessmentForm(){modal('记录一次阶段测评',`<p class="subtext">填练习正确率（0–100%）。不同难度、不同题量之间不能直接比较；尽量记录材料和用时。</p><form id="assessment-form" class="form-grid"><label class="wide">材料 / 测评名称 *<input name="source" required maxlength="300" placeholder="例如：N3 教材第4章新题"></label><label>词汇语法正确率 %<input name="language" type="number" min="0" max="100" required></label><label>阅读正确率 %<input name="reading" type="number" min="0" max="100" required></label><label>听力正确率 %<input name="listening" type="number" min="0" max="100" required></label><label class="wide">用时、错因与下一步<textarea name="note" maxlength="2000" rows="3" placeholder="如：听力首听50%，复听75%；主要没听清时间变化。"></textarea></label><button class="button wide" type="submit">保存测评</button></form>`);}
function exportBackup(){persist();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`日日-学习备份-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，导入前请核对日期。');}
let pendingBackup=null;
async function importBackup(file){if(!file)return;if(file.size>8*1024*1024){toast('文件过大，请选择本站导出的 JSON 备份。');return;}try{pendingBackup=validateBackup(JSON.parse(await file.text()));modal('核对这份备份',`<p class="subtext">这份备份包含 ${Object.keys(pendingBackup.days).length} 天记录、${pendingBackup.custom.length} 个自添词、${pendingBackup.notes.length} 条笔记。导入会替换当前设备记录。</p><p class="subtext">建议先导出当前备份。导入不会合并两台设备的数据。</p><div class="button-row"><button class="button ghost" data-action="export">先导出当前备份</button><button class="button" data-action="confirm-import">确认替换并导入</button></div>`);}catch(e){pendingBackup=null;toast('无法导入：'+e.message);}}
function speak(text,rate=1){if(!('speechSynthesis'in window)){toast('这个浏览器不支持朗读，请使用官方真人听力资料。');return;}const synth=window.speechSynthesis;const voices=synth.getVoices();const voice=voices.find(v=>v.lang.toLowerCase().startsWith('ja'));if(!voice){toast('未找到设备日语声音。请开启或安装日语语音，或使用官方真人听力资料。');return;}synth.cancel();const utterance=new SpeechSynthesisUtterance(text.replace(/男：|女：|先生：/g,''));utterance.lang='ja-JP';utterance.voice=voice;utterance.rate=rate;utterance.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('语音播放未成功，请检查设备日语声音或打开官方音频。');};synth.speak(utterance);}
function openTimer(){if(!focusRunning&&focusedLogged===0){focusTotal=state.minutes*60;focusRemaining=focusTotal;}modal('给自己一段专注时间',`<p class="subtext">边学边计时。记录实际经过的时间；后台运行时再次打开会更新。中途暂停也会保留已学时间。</p><div style="text-align:center"><div id="timer-display" class="timer">${timerText()}</div><div class="button-row" style="justify-content:center"><button class="button" id="timer-toggle" data-action="toggle-timer">${focusRunning?'暂停':'开始 / 继续'}</button><button class="button ghost" data-action="reset-timer">结束本次</button></div></div><p class="panel-note">专注时间与任务完成分别记录。计时完成后，请自行确认做完了哪些任务。</p>`);}
function timerText(){return `${String(Math.floor(focusRemaining/60)).padStart(2,'0')}:${String(Math.floor(focusRemaining%60)).padStart(2,'0')}`;}
function tickTimer(){if(!focusRunning)return;const now=Date.now(),remaining=Math.max(0,Math.ceil((focusEnd-now)/1000));const delta=focusRemaining-remaining;if(delta>0){currentDay().focusSeconds=Math.min(86400,currentDay().focusSeconds+delta);focusedLogged+=delta;focusRemaining=remaining;if(focusedLogged%10===0||!remaining)persist();}const el=$('#timer-display');if(el)el.textContent=timerText();if(!remaining){focusRunning=false;clearInterval(focusInterval);persist();const btn=$('#timer-toggle');if(btn)btn.textContent='已完成';toast('专注结束，把今天学到的一点记录下来。');render();}}
function toggleTimer(){if(focusRunning){tickTimer();focusRunning=false;clearInterval(focusInterval);persist();}else if(focusRemaining>0){focusRunning=true;focusEnd=Date.now()+focusRemaining*1000;focusInterval=setInterval(tickTimer,1000);}openTimer();}
function checkListening(){const l=activeListen();if(selectedChoice===null||listenAnswered)return;listenAnswered=true;const id=`${l.id}:${today}`;if(!currentDay().listening.includes(id))currentDay().listening.push(id);if(selectedChoice!==l.answer)addNote('listen-'+l.id,'听力错题：'+l.title,l.question+'\n正确答案：'+l.options[l.answer]+'\n'+l.explanation,'听力');persist();render();}
function checkReading(){const r=FOUNDATION.reading.find(x=>x.id===readingId);if(r.questions.some((_,i)=>readAnswers[i]===undefined))return;readChecked=true;currentDay().tasks.grammar_reading=true;if(!currentDay().reading.includes(r.id))currentDay().reading.push(r.id);r.questions.forEach((q,i)=>{if(readAnswers[i]!==q.answer)addNote('read-'+r.id+'-'+i,'阅读错题：'+r.title,q.prompt+'\n'+q.explanation,'阅读');});persist();render();}
function finishDiagnostic(){diagnosticFinished=true;const qs=FOUNDATION.diagnostic,score=diagnosticAnswers.reduce((n,a,i)=>n+(a===qs[i].answer),0);state.diagnostic={date:today,score,weakAreas:[...new Set(qs.filter((q,i)=>diagnosticAnswers[i]!==q.answer).map(q=>q.area))]};persist();render();window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){
  case 'settings':settings();break;case 'close-modal':$('#modal').close();break;case 'today':go('today');break;case 'plan':go('plan');break;
  case 'start-today':{const next=tasks().find(t=>!currentDay().tasks[t.type]);study(next?.tab||'vocabulary');break;}
  case 'study-tab':study(id);break;case 'toggle-task':currentDay().tasks[id]=!currentDay().tasks[id];persist();render();break;
  case 'reveal-card':cardRevealed=true;render();break;case 'rate':rateCard(id);break;case 'complete-vocab':currentDay().tasks.vocabulary=true;persist();go('today');toast('词汇任务已记下，明天再见。');break;
  case 'add-word':addWord();break;case 'speak-word':{const v=vocab().find(x=>x.id===id);if(v)playWordAudio(v);break;}
  case 'save-grammar':{const g=DATA.grammar.find(x=>x.id===id);addNote('grammar-'+id,g.title,g.usage+'\n'+g.example+'\n'+g.exampleZh,'语法');persist();toast('已收藏到积累手账。');break;}
  case 'learn-grammar':state.grammar[id]=today;persist();render();toast('已记录学过；练完造句后，在首页勾选语法任务。');break;
  case 'speak-grammar':speak(DATA.grammar.find(g=>g.id===id).example);break;
  case 'play-listening':speak(activeListen().script,Number($('#audio-speed').value));break;case 'stop-speech':if('speechSynthesis'in window)window.speechSynthesis.cancel();break;
  case 'listen-choice':selectedChoice=Number(id);render();break;case 'check-listening':checkListening();break;case 'toggle-script':showScript=!showScript;render();break;
  case 'reset-listening':selectedChoice=null;listenAnswered=false;showScript=false;render();break;case 'complete-listening':currentDay().tasks.listening=true;persist();go('today');toast('精听任务已记录，隔天再听这段。');break;
  case 'read-choice':{const [q,a]=id.split(':').map(Number);readAnswers[q]=a;render();break;}case 'check-reading':checkReading();break;case 'reset-reading':readAnswers={};readChecked=false;render();break;
  case 'set-phase':state.phase=Number(id);state.level=state.phase<2?'foundation':'n2';state.vocabStage=state.phase===0?'foundation':state.phase===1?'bridge':'n2';queueActive=false;persist();render();toast('当前阶段已更新。时间表是建议，以测评情况调整。');break;
  case 'diagnostic':go('diagnostic');break;case 'diagnostic-choice':diagnosticAnswers[diagnosticIndex]=Number(id);render();break;case 'diagnostic-next':if(diagnosticAnswers[diagnosticIndex]===undefined)break;if(diagnosticIndex===FOUNDATION.diagnostic.length-1)finishDiagnostic();else{diagnosticIndex++;render();}break;
  case 'add-note':addNoteForm();break;case 'delete-note':state.notes=state.notes.filter(n=>n.id!==id);persist();render();break;
  case 'assessment':assessmentForm();break;case 'export':exportBackup();break;case 'confirm-import':if(pendingBackup){if(focusRunning)tickTimer();focusRunning=false;clearInterval(focusInterval);state=pendingBackup;pendingBackup=null;queueActive=false;cardRevealed=false;focusedLogged=0;focusRemaining=state.minutes*60;persist();$('#modal').close();go('today');toast('备份已导入。');}break;
  case 'timer':openTimer();break;case 'toggle-timer':toggleTimer();break;case 'reset-timer':if(focusRunning)tickTimer();focusRunning=false;clearInterval(focusInterval);persist();focusRemaining=state.minutes*60;focusedLogged=0;$('#modal').close();render();toast('已保留本次专注时间。');break;
}});
document.addEventListener('change',e=>{if(e.target.id==='audio-speed')audioRate=Number(e.target.value);if(e.target.id==='level'){state.level=e.target.value;queueActive=false;listeningId=null;selectedChoice=null;listenAnswered=false;readChecked=false;readAnswers={};persist();if('speechSynthesis'in window)window.speechSynthesis.cancel();render();}if(e.target.id==='minutes-pick'){state.minutes=Number(e.target.value);persist();render();toast('每日计划已调整为 '+state.minutes+' 分钟。');}if(e.target.id==='listening-pick'){listeningId=e.target.value;selectedChoice=null;listenAnswered=false;showScript=false;if('speechSynthesis'in window)window.speechSynthesis.cancel();render();}if(e.target.id==='reading-pick'){readingId=e.target.value;readAnswers={};readChecked=false;render();}if(e.target.id==='backup-file')importBackup(e.target.files[0]);});
document.addEventListener('submit',e=>{if(!['word-form','note-form','assessment-form'].includes(e.target.id))return;e.preventDefault();const fd=new FormData(e.target),v=Object.fromEntries(fd);if(e.target.id==='word-form'){if(!v.word.trim()||!v.meaning.trim()){toast('请填写单词和中文意思。');return;}if(vocab().some(w=>w.word===v.word.trim()&&w.reading===v.reading.trim())){toast('词卡里已有这个词，请换一个新词。');return;}state.custom.push({id:'c-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),level:(v.stage||v.level)==='n2'?'n2':'foundation',stage:v.stage||v.level||state.vocabStage,word:v.word.trim(),reading:v.reading.trim(),meaning:v.meaning.trim(),example:v.example.trim(),exampleZh:v.exampleZh.trim()});queueActive=false;toast('已加入词卡，按每日上限安排新词。');}if(e.target.id==='note-form'){addNote('note-'+Date.now(),v.title.trim(),v.body.trim(),'随笔');toast('笔记已保存。');}if(e.target.id==='assessment-form'){const a={date:today,source:v.source.trim(),language:Number(v.language),reading:Number(v.reading),listening:Number(v.listening),note:v.note.trim()};if(!['language','reading','listening'].every(k=>a[k]>=0&&a[k]<=100)){toast('正确率请填写 0–100。');return;}state.assessments.push(a);toast('测评结果已记下。');}persist();$('#modal').close();render();});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(navItems.some(([id])=>id===r))go(r);});
window.addEventListener('pagehide',()=>{if(focusRunning)tickTimer();persist();if('speechSynthesis'in window)window.speechSynthesis.cancel();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tickTimer();if(dayKey()!==today)render();}else persist();});
if('speechSynthesis'in window)window.speechSynthesis.getVoices();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
route=navItems.some(([id])=>id===location.hash.slice(1))?location.hash.slice(1):'today';render();
